import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","frontmatter":{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","splitFrom":"life/personal/yijing/hexagrams-09-16.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读二：小畜履泰否至同人大有谦豫","summary":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件","link":"/life/personal/yijing/hexagrams-09-16-part-01"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测","link":"/life/personal/yijing/hexagrams-09-16-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件","link":"/life/personal/yijing/hexagrams-09-16-part-01"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测","link":"/life/personal/yijing/hexagrams-09-16-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-09-16-part-02.md","filePath":"life/personal/yijing/hexagrams-09-16-part-02.md"}'),o={name:"life/personal/yijing/hexagrams-09-16-part-02.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读二-小畜履泰否至同人大有谦豫-·-12-否-闭塞之中保存原则至14-大有-拥有越多-越须承担分配责任" tabindex="-1">六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任 <a class="header-anchor" href="#六十四卦详读二-小畜履泰否至同人大有谦豫-·-12-否-闭塞之中保存原则至14-大有-拥有越多-越须承担分配责任" aria-label="Permalink to &quot;六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-09-16">返回分篇目录</a></p><p>本组特别适合成对阅读：小畜与履讨论限制和行进，泰与否呈现通塞，同人与大有讨论联结和拥有，谦与豫则观察自处及群体情绪。所谓“好卦”也包含风险，“坏卦”中也可能出现可行之道。</p><p>本文逐卦对读《周易》经传与王弼注、孔颖达疏《周易正义》。引文是古籍原文，表格解释与读法为本篇白话概括；通行字句参照《正义》，如小畜的“輿說輻”、大有的“匪其彭”，并提示异文。标点属整理，不应误以为古本原有。占断是古代文化材料，本文讨论其结构与思想，不据此预测现实结果。</p><h2 id="gua-12" tabindex="-1">12 否：闭塞之中保存原则 <a class="header-anchor" href="#gua-12" aria-label="Permalink to &quot;12 否：闭塞之中保存原则 {#gua-12}&quot;">​</a></h2><p><strong>卦符：䷋　上卦：乾 ☰（天）　下卦：坤 ☷（地）。否读 pǐ，意为闭塞。</strong></p><p><strong>卦辞原文</strong>：否之匪人，不利君子貞，大往小來。</p><p><strong>白话概括</strong>：天地不交、上下隔绝，是否的整体意象。《正义》将“匪人”解释为不是人道交通的时候，不宜只译为遇到坏人。君子守正受到不利条件，也并非原则已经无价值；它要求认识环境，避免把一切责任归咎于个人不够努力。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：拔茅茹，以其彙，貞吉，亨。</td><td>同样有根系相连之象，与泰初九不同，这里突出守正而非征进。结伴应先辨清方向。</td></tr><tr><td>六二：包承，小人吉，大人否，亨。</td><td>包容承顺可使小人得利，大人却不必混入其群。“大人否亨”的断句与层次须结合古注，不能笼统劝人逢迎。</td></tr><tr><td>六三：包羞。</td><td>所包藏的是羞耻，揭示不当位置与行为。短句没有直接写凶，却不意味着可以忽略其负面判断。</td></tr><tr><td>九四：有命，无咎，疇離祉。</td><td>有合宜使命或时命才可行动，同类得以分享福祉。命与畴离的解释存在差异，应避免当成自封天命。</td></tr><tr><td>九五：休否，大人吉。其亡其亡，繫于苞桑。</td><td>使闭塞停止，仍反复警惕可能失去，像系于牢固桑根。好转时巩固基础，而非宣布风险消失。</td></tr><tr><td>上九：傾否，先否後喜。</td><td>闭塞被倾覆，先困后喜。它描述卦中终极转变，不保证每一个现实困局都会自然结束。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天地不交，否；君子以儉德辟難，不可榮以祿。”</p><p><strong>解释</strong>：收敛外显、避开危险，不以禄位诱惑改变原则。俭德不是放弃德性，而是减少在不合宜环境中的炫露；古代出处观念也不能用来阻止合理维权和公共表达。</p><p><strong>整体读法与误区</strong>：否的阅读次序是先承认不通，再辨是否存在可以行动的条件。九四有命、九五休否、上九倾否，并非任何时刻都可强行套用。常说“否极泰来”，只概括一类变化观；若据此拒绝求助或修复现实问题，就把反省文本变成了消极宿命论。</p><p><strong>细读线索</strong>：把否与泰的初爻逐字对照，会发现两者都写拔茅，却一个重征、一个重贞。相同意象随着卦时改变而获得不同要求，这是学习爻辞不能离卦的直接例子。否的中段又分包承和包羞：有人因承顺受益，有人内含羞耻，不能把处于闭塞时期的人一概分类为同一种角色。九五休否之后的其亡其亡，则把警觉放在局面已经好转之时。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6" target="_blank" rel="noopener noreferrer">《周易·否》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%90%A6" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·否》</a>。</p><h2 id="gua-13" tabindex="-1">13 同人：共同之中容纳差异 <a class="header-anchor" href="#gua-13" aria-label="Permalink to &quot;13 同人：共同之中容纳差异 {#gua-13}&quot;">​</a></h2><p><strong>卦符：䷌　上卦：乾 ☰（天）　下卦：离 ☲（火、明）。</strong></p><p><strong>卦辞原文</strong>：同人于野，亨。利涉大川，利君子貞。</p><p><strong>白话概括</strong>：在开阔处与人相同，而非只在亲族与私党之间相合。《正义》以“野”喻用心宽广、没有狭隘私意；它又提醒和同也可能走向邪僻，因此必须加上“君子贞”。共同体不是意见一律一致，而是有可以共同承担的正当原则。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：同人于門，无咎。</td><td>走出门户与人相接，尚无私狭之咎。门是关系打开的起点。</td></tr><tr><td>六二：同人于宗，吝。</td><td>只与同宗、同党相合，范围狭隘。它不是否定亲情，而是警告把公共关系缩成小圈子。</td></tr><tr><td>九三：伏戎于莽，升其高陵，三歲不興。</td><td>暗藏兵戎、登高窥伺，却长期不能行动。同人卦也写猜忌与竞争，并非满篇和气。</td></tr><tr><td>九四：乘其墉，弗克攻，吉。</td><td>已登上城墙，却停止进攻；不能或不应攻时回头，反而为吉。墉也有作庸的异文。</td></tr><tr><td>九五：同人，先號啕而後笑。大師克相遇。</td><td>相合先遇阻隔而哭，后得相遇而笑，其间有强力冲突。不能把“大师克”抹去，只保留团圆的浪漫叙事。</td></tr><tr><td>上九：同人于郊，无悔。</td><td>在郊外相处，虽无悔，却未必达到卦辞所说开阔通达；《小象》还说志未得。无悔不等于圆满。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天與火，同人；君子以類族辨物。”</p><p><strong>解释</strong>：天地火明的取象，引出辨别类别、理解差异。既然讲同人，为什么还讲辨物？正因为相同不是混成一团；不同职责、对象和需要都应被看见，才有适当的相处方式。</p><p><strong>整体读法与误区</strong>：从门到宗、莽、墉、郊、野，空间意象帮助观察关系究竟在打开还是收缩。若只凭“同人”二字劝所有人无条件一致，就忽略六二的私狭与三四爻的攻击。可以讨论共同目标，也必须保留合理分歧与退出边界；古代动兵取象更不能直接授权现实中的强制。</p><p><strong>细读线索</strong>：同人只有六二一阴，古注以其得中得位、与九五相应说明全卦，但六二自身仍被判为于宗之吝。这再次提醒：形成某卦的关键条件，不等于相关爻可以免受批评。三、四两爻围绕相合出现伏兵和攻墙，显示希望相同有时反而引起争夺。大象的辨物因此不是多余步骤：承认差异、明确归属与边界，才能避免把相合变成对唯一对象的竞争。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%8C%E4%BA%BA" target="_blank" rel="noopener noreferrer">《周易·同人》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%90%8C%E4%BA%BA" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·同人》</a>。</p><h2 id="gua-14" tabindex="-1">14 大有：拥有越多，越须承担分配责任 <a class="header-anchor" href="#gua-14" aria-label="Permalink to &quot;14 大有：拥有越多，越须承担分配责任 {#gua-14}&quot;">​</a></h2><p><strong>卦符：䷍　上卦：离 ☲（火、明）　下卦：乾 ☰（天、健）。</strong></p><p><strong>卦辞原文</strong>：大有：元亨。</p><p><strong>白话概括</strong>：所拥有的广大，来自上下相应和明健相配，而非孤立个人无止境占有。《正义》以六五柔居尊位、众阳相应说明大有，特别强调能够容纳。看似最简洁的吉辞，落在各爻中仍有艰难、自抑、诚信与威仪等条件。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：无交害，匪咎，艱則无咎。</td><td>尚未与有害因素相交，仍要以艰难之心自处。没有眼前问题不代表往后不会出问题。</td></tr><tr><td>九二：大車以載，有攸往，无咎。</td><td>大车能够承担载荷，才可有所往。拥有与承载能力相称，比只看数量更重要；车字另有轝等异文。</td></tr><tr><td>九三：公用亨于天子，小人弗克。</td><td>诸侯参与天子的享礼或通达其上，小人不能胜任。亨、享的解释应联系礼制，不宜只读成个人亨通。</td></tr><tr><td>九四：匪其彭，无咎。</td><td>不自处于盛满炫耀之中，故无咎。彭在古注中多向盛大解释，另有字形异文，不能按现代姓氏理解。</td></tr><tr><td>六五：厥孚交如，威如，吉。</td><td>诚信能够相交，同时保有应有的威仪与边界。亲和不必取消规则，威严也不必依靠恐惧。</td></tr><tr><td>上九：自天祐之，吉无不利。</td><td>经文以天佑表达总体嘉许。《系辞》另从信、顺、尚贤加以阐释，不是无条件的超自然保险。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“火在天上，大有；君子以遏惡揚善，順天休命。”</p><p><strong>解释</strong>：火高而明，持有资源和权位者应辨别善恶、让好的行为得到支持。“休命”是美善之命。大有的重点因此不仅是拥有，更包括资源与影响力如何使用。</p><p><strong>整体读法与误区</strong>：与<a href="/life/personal/yijing/hexagrams-09-16-part-02#gua-13">同人</a>交换上下卦后，重点从“怎样相合”转成“广大所有怎样被维持”。初九艰、九四抑、六五孚威并用，都是对过满的约束。把大有当作发财符，会漏掉公共责任和承载能力；把六五的威如解释为高压，也会割裂它与诚信相交的前提。</p><p><strong>细读线索</strong>：大有与同人共用乾离而上下互换，大有的六五成为一阴居尊而受众阳响应的位置。古注由此强调以柔处尊，并不是把数量最多的一方必然视作主导。九二的大车提供承载图像，九三的享礼提供共同秩序，六五的孚与威提供关系方式。这三层串起来，拥有才不是孤立库存，而是能够承载、分配并维持信任的公共条件。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E6%9C%89" target="_blank" rel="noopener noreferrer">《周易·大有》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%A4%A7%E6%9C%89" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·大有》</a>。</p>',34)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
